from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_divs = [r for r,row in enumerate(grid) if len(set(row)) == 1]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def regions(n, divs):
        out=[]; start=0
        for d in divs:
            if d >= start:
                if start < d: out.append(list(range(start,d)))
                start=d+1
        if start<n: out.append(list(range(start,n)))
        return [x for x in out if x]
    rs, cs = regions(h,row_divs), regions(w,col_divs)
    # Find divider color, then region base = most frequent color not divider; marker is remaining non-base color.
    divcolors = {grid[r][0] for r in row_divs} | {grid[0][c] for c in col_divs}
    counts=Counter(v for row in grid for v in row if v not in divcolors)
    bg=counts.most_common(1)[0][0]
    # The marker is the non-background, non-divider color.
    markers={v for row in grid for v in row if v not in divcolors and v != bg}
    marker=next(iter(markers))
    output=[]
    for rr in rs:
        outrow=[]
        for cc in cs:
            n=sum(grid[r][c]==marker for r in rr for c in cc)
            outrow.append(1 if n>1 else bg)
        output.append(outrow)
    return output

